package com.daniil.wristlens.phone;
import com.google.android.gms.wearable.*;import com.google.android.gms.tasks.Tasks;import com.daniil.wristlens.shared.Wire;import android.util.Base64;import org.json.*;import java.util.concurrent.*;
/** Nearby paired nodes can access only entries created by this app. */
public final class MediaBridgeService extends WearableListenerService {
 private final ExecutorService io=Executors.newFixedThreadPool(2);
 @Override public void onMessageReceived(MessageEvent e){if(!e.getPath().equals(Wire.MEDIA))return;String node=e.getSourceNodeId();byte[] data=e.getData();io.execute(()->{String request="";try{if(!Tasks.await(Wearable.getNodeClient(this).getConnectedNodes(),8,TimeUnit.SECONDS).stream().anyMatch(n->n.isNearby()&&n.getId().equals(node)))return;JSONObject j=Wire.parse(data);request=j.getString("request");MediaFiles files=new MediaFiles(this);JSONObject result;switch(j.getString("op")){
  case "list"->result=Wire.object("items",files.list(j.optInt("offset")),"storage",files.settings(),"cursor",files.latest(),"total",files.count());
  case "index"->result=files.index(j.optLong("before",Long.MAX_VALUE),j.optLong("snapshot",files.latest()));
  case "sync"->result=Wire.object("items",files.since(j.getLong("cursor")));
  case "thumb"->{int size=Math.max(64,Math.min(640,j.optInt("size",160)));byte[] bytes=files.thumbnail(j.getString("id"),size);while(bytes.length>45000&&size>80){size=size*3/4;bytes=files.thumbnail(j.getString("id"),size);}result=Wire.object("jpeg",Base64.encodeToString(bytes,Base64.NO_WRAP));}
  case "delete"->{files.deleteEntry(j.getString("id"));result=Wire.object("deleted",true);}
  case "delete_many"->{JSONArray ids=j.getJSONArray("ids"),deleted=new JSONArray(),errors=new JSONArray();if(ids.length()>50)throw new IllegalArgumentException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_19));for(int i=0;i<ids.length();i++){String id=ids.getString(i);try{files.deleteEntry(id);deleted.put(id);}catch(Exception x){errors.put(Wire.object("id",id,"message",x.getMessage()));}}result=Wire.object("deleted",deleted,"errors",errors);}
  case "share"->{JSONArray ids=j.getJSONArray("ids");if(ids.length()==0||ids.length()>500)throw new IllegalArgumentException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_20));for(int i=0;i<ids.length();i++)files.find(ids.getString(i));result=Wire.object("token",Tickets.issue(this,"launch",node,"share:"+ids));}
  case "file"->{MediaFiles.Entry entry=files.find(j.getString("id"));if(entry.bytes()<=0||entry.bytes()>com.daniil.wristlens.core.OriginalTransfer.MAX)throw new IllegalStateException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_075));result=entry.json();String value=entry.id();if(j.optInt("copyProtocol")==2){String photo=com.daniil.wristlens.core.CopyProfile.of(j.optString("photo","original")).id(),video=com.daniil.wristlens.core.CopyProfile.of(j.optString("video","original")).id();value=Wire.object("id",entry.id(),"photo",photo,"video",video).toString();result.put("copyProtocol",2);}result.put("token",Tickets.issue(this,"file",node,value));}
  case "launch"->{String action=j.optString("action","start");if(!java.util.List.of("start","folder","media","microphone").contains(action))throw new IllegalArgumentException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_076));String value=action.equals("media")?"media:"+files.find(j.getString("id")).id():action;result=Wire.object("token",Tickets.issue(this,"launch",node,value));}
  case "disconnect"->{CameraService camera=CameraService.instance;if(camera==null)result=Wire.object("disconnected",true);else{camera.disconnect(node,j.optString("session"),error->reply(node,j.optString("request"),error.isEmpty()?Wire.object("disconnected",true):Wire.object("error",error)));return;}}
  case "capture_settings"->{CaptureOptions options=new CaptureOptions(this);if(j.has("key")){CameraService camera=CameraService.instance;if(camera!=null){camera.local(j,error->reply(node,j.optString("request"),error.isEmpty()?Wire.object("capture",options.json()):Wire.object("error",error)));return;}options.apply(j);}result=Wire.object("capture",options.json());}
  case "storage"->{CameraService camera=CameraService.instance;if(camera!=null){camera.local(j,error->reply(node,j.optString("request"),error.isEmpty()?Wire.object("storage",files.settings()):Wire.object("error",error)));return;}files.setting(j);result=Wire.object("storage",files.settings());}
  default->throw new IllegalArgumentException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_077));
 }reply(node,request,result);}catch(Exception x){reply(node,request,Wire.object("error",x.getMessage()==null?com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_078):x.getMessage()));}});}
 private void reply(String node,String request,JSONObject result){try{result.put("request",request);Wearable.getMessageClient(this).sendMessage(node,Wire.MEDIA_RESULT,Wire.bytes(result));}catch(Exception ignored){}}
 @Override public void onChannelOpened(ChannelClient.Channel channel){if(!channel.getPath().startsWith(Wire.FILE))return;try{String token=channel.getPath().substring(Wire.FILE.length());JSONObject j=Tickets.consume(this,token,"file",channel.getNodeId());MediaTransferService.start(this,channel,j.getString("value"));}catch(Exception e){Wearable.getChannelClient(this).close(channel);}}
 @Override public void onDestroy(){io.shutdown();super.onDestroy();}
}
